prts.feedbackvariables:
isansFalse2: is(ans3 = false);
isansFalse3: is(ans4 = false);
isansFalse4: is(ans5 = false);
isansVector2: is(matrixp(ans3) and length(ans3)=dims[2] and length(ans3[1])=1);
isansVector3: is(matrixp(ans4) and length(ans4)=dims[2] and length(ans4[1])=1);
isansVector4: is(matrixp(ans5) and length(ans5)=dims[2] and length(ans5[1])=1);
validInput2: isansFalse2 or isansVector2;
validInput3: isansFalse3 or isansVector3;
validInput4: isansFalse4 or isansVector4;
validInput: validInput2 and validInput3 and validInput4;

vects: delete(false, [ans3,ans4,ans5]);
len: length(vects);
generalSolMat: if(validInput and len >=1) then block([mat],mat: matrix([]),for i:1 thru len do(mat: addcol(mat,vects[i])),mat) else zeromatrix(dims[2],dims[2]-rk);
linearlyIndSol: is(rank(generalSolMat) = len);
fullDimSol: is(rank(generalSolMat) = dims[2]-rk);
generalSolAreSols: if (validInput) then is(exEch.generalSolMat = zeromatrix(dims[1],dims[2]-rk)) else false;

